// Validate matches response from API
const content = $input.first().json;

if (!content || !content.generatedAt || !Array.isArray(content.tennis) || !Array.isArray(content.football)) {
  throw new Error('Invalid matches response from API');
}

return [{ json: content }];

// Build batch payload for prediction engine
const matches = $input.first().json;
const batch = [];

for (const match of matches.tennis) {
  batch.push({ sport: 'tennis', match: match });
}

for (const match of matches.football) {
  batch.push({ sport: 'football', match: match });
}

return [{ json: { matches: batch } }];

// Parse prediction engine stdout (JSON array)
const stdout = $input.first().json.stdout;
let results;
try {
  results = JSON.parse(stdout);
} catch (e) {
  throw new Error('Prediction engine returned invalid JSON: ' + stdout);
}
if (!Array.isArray(results)) {
  results = [results];
}
return results.map(r => ({ json: r }));

// Aggregate all engine outputs into predictions batch
const items = $input.all();
const predictions = [];

for (const item of items) {
  const engineOutput = item.json;
  if (engineOutput.error || !engineOutput.predictions) continue;
  const matchId = engineOutput.matchId;
  const sport = engineOutput.sport;
  const enginePredictions = engineOutput.predictions || [];

  for (const pred of enginePredictions) {
    predictions.push({
      matchId: matchId,
      sport: sport,
      market: pred.market,
      prediction: pred.prediction,
      confidence: pred.confidence,
      reasoning: pred.reasoning || '',
      naturalLanguageReasoning: pred.naturalLanguageReasoning || engineOutput.naturalLanguageReasoning || '',
      probabilities: pred.probabilities || {},
      modelContributions: pred.modelContributions || {},
      reasoningData: pred.reasoningData || {}
    });
  }
}

const now = new Date();
const datePrefix = now.toLocaleDateString('en-CA', { timeZone: 'America/Bogota' }).replace(/-/g, '');
function stableHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h) + str.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString().padStart(5, '0');
}
for (let i = 0; i < predictions.length; i++) {
  const p = predictions[i];
  const suffix = stableHash(`${p.matchId}|${p.market}`).slice(0, 5);
  p.predictionId = `PRED-${datePrefix}-${suffix}`;
  p.status = 'PENDING';
}

const generatedAt = now.toISOString();
const output = {
  generatedAt: generatedAt,
  source: 'prediction_engine',
  predictions: predictions
};

return [{ json: output }];

const data = $('Build Predictions Output').first().json;
const dbResult = $input.first().json || {};
const count = data.predictions ? data.predictions.length : 0;
const inserted = dbResult.inserted || 0;
const updated = dbResult.updated || 0;
const errors = dbResult.errors ? dbResult.errors.length : 0;

const matchesBySport = {};
const predBySport = {};
for (const pred of (data.predictions || [])) {
  const sport = pred.sport || 'unknown';
  matchesBySport[sport] = matchesBySport[sport] || new Set();
  matchesBySport[sport].add(pred.matchId);
  predBySport[sport] = (predBySport[sport] || 0) + 1;
}

let sportLines = '';
for (const sport of Object.keys(matchesBySport).sort()) {
  sportLines += `\n- ${sport}: ${matchesBySport[sport].size} partidos, ${predBySport[sport]} predicciones`;
}
const predictedMatches = Object.values(matchesBySport).reduce((a, s) => a + s.size, 0);

const telegramMessage = `<b>BrainBets - Predicciones Generadas</b>\n\nModelos: Prediction Engine\nTotal predicciones: ${count}\nPartidos predichos: ${predictedMatches}${sportLines}\n\nInsertadas: ${inserted}\nActualizadas: ${updated}\nErrores: ${errors}`;
return [{
  json: {
    telegramMessage: telegramMessage,
    dbResult: dbResult
  }
}];
